// function createProduct(name, price, category)
// Name empty: "Name required"
// Price <= 0: "Invalid price"
// Category empty: "Category required"
// Warna product object return karo

solution:
function createProduct(name, price, category) {
  if (!name || name.trim().length === 0) return "Name required"
  if (typeof price !== "number" || price <= 0) return "Invalid price"
  if (!category || category.trim().length === 0) return "Category required"
  return { name: name.trim(), price, category: category.trim() }
}
